import{_ as n,o as r,c as s,j as e,a as t,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/import-export-statistik/verwaltung-statistik.png",p=JSON.parse('{"title":"Die Statistikfunktionen in SchILD-NRW verwenden","description":"","frontmatter":{"title":"Die Statistikfunktionen in SchILD-NRW verwenden","source_pageid":296,"source_revision":3359},"headers":[],"relativePath":"schild3/import-export-statistik/statistik-fuer-it-nrw-verwaltung.md","filePath":"schild3/import-export-statistik/statistik-fuer-it-nrw-verwaltung.md"}'),o={name:"schild3/import-export-statistik/statistik-fuer-it-nrw-verwaltung.md"};function d(u,i,h,c,g,k){return r(),s("div",null,[...i[0]||(i[0]=[e("h1",{id:"die-statistikfunktionen-in-schild-nrw-verwenden",tabindex:"-1"},[t("Die Statistikfunktionen in SchILD-NRW verwenden "),e("a",{class:"header-anchor",href:"#die-statistikfunktionen-in-schild-nrw-verwenden","aria-label":'Permalink to "Die Statistikfunktionen in SchILD-NRW verwenden"'},"​")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),t("Hinweis – Geltungsbereich: ASDPC-Verfahren")]),e("p",null,[t("Dieser Artikel beschreibt die Vorbereitung beziehungsweise Nutzung des bisherigen ASDPC-Verfahrens. Für die amtliche Erhebung "),e("strong",null,"ab dem Schuljahr 2027/2028"),t(" ist die Umstellung auf das Statistikmodul des SVWS-Servers angekündigt. Beachten Sie den "),e("a",{href:"https://www.svws.nrw.de/statistik/asdpc-svws-server",target:"_blank",rel:"noreferrer"},"offiziellen Zeitplan"),t(" und die Vorgaben der jeweiligen Erhebung.")])],-1),a('<p>Prüfen Sie Daten, öffnen Sie das Fehlerprotokoll und exportieren Sie die benötigten Statistikdateien. Die Funktionen dienen der Vorbereitung der anschließenden Arbeit in ASDPC.</p><p><a href="/bilder/import-export-statistik/verwaltung-statistik.png"><img src="'+l+'" alt="Werkzeuge, die bei der Statistik unterstützen." loading="lazy"></a></p><p><em>Werkzeuge, die bei der Statistik unterstützen.</em></p><p>SchILD unterstützt Sie bei der Erstellung der Statistik, indem im Vorfeld Daten geprüft und dann exportiert werden können.</p><ul><li><strong>Gesamtprüfung der Daten</strong> führt eine Prüfung der Daten auf und zeigt offensichtliche Fehler an, die vor der Arbeit mit dem Statistikprogramm bereinigt werden müssen. Hier fallen vor allem, aber nicht nur, fehlende Einträge auf.</li><li><strong>Fehlerprotokoll anzeigen</strong>: wurde eine Statistikprüfung durchgeführt, lässt sich mit diesem Schalter das Fehlerprotokoll anzeigen. Nehmen Sie hier bitte auch die Möglichkeit wahr, über <em>Auswahl</em> die Schaltfläche <strong>Schüler mit Statistikfehlern anzeigen</strong> zu nutzen, um ein &quot;interaktives Fehlerprotokoll&quot; zu starten.</li><li><strong>Daten exportieren</strong> öffnet den Exportdialog, über den <em>SIM.txt</em> (Schülerdaten), <em>LID.txt</em> (Lehrerdaten), <em>UVD.txt</em> (die Unterrichtsverteilung) und <em>Abi.txt</em> (Abitur) exportiert werden können.</li><li><strong>Hilfe bei Problemen</strong>: SchILD-NRW benötigt die Registrierung externer Bibliotheken in Windows. Wurde SchILD-NRW nicht auf dem aktuellen Rechner installiert, sondern nur als Client gestartet, kann die Registrierung mit dieser Schaltfläche angestoßen werden. Hinweis: Sie benötigen lokale Administratorrechte für diesen Vorgang.</li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Statistik_f%C3%BCr_IT.NRW_(Verwaltung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 3359.</p>',7)])])}const m=n(o,[["render",d]]);export{p as __pageData,m as default};
